{

    const char *p = p1->buf, *p_end = p1->buf + p1->buf_size;



    /* we look for a line beginning "c=IN IP" */

    while (p < p_end && *p != '\0') {

        if (p + sizeof("c=IN IP") - 1 < p_end &&

            av_strstart(p, "c=IN IP", NULL))

            return AVPROBE_SCORE_EXTENSION;



